{"task": "Identify user requests with pagination parameters in URLs", "sql": "SELECT * FROM events WHERE regexp_like(path, '\\?page=\\d+&size=\\d+')"}
{"task": "Extract logs showing database connection errors from specific services", "sql": "SELECT ts, service, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, 'database.*connection.*failed') AND regexp_like(service, '^(auth|api)-service$')"}
{"task": "Find API requests with authentication token parameters in query strings", "sql": "SELECT * FROM events WHERE regexp_like(path, '\\?token=[a-zA-Z0-9\\-_]+')"}
{"task": "Identify log messages containing stack trace information for specific modules", "sql": "SELECT ts, message FROM logs WHERE regexp_like(message, 'java\\.lang\\.Exception.*at .*\\.(.*)\\(.*\\)') AND regexp_like(service, 'webapp-(api|service)-.*')"}
