{"task": "Find error logs related to file upload operations with specific extensions", "sql": "SELECT ts, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, '\\.(jpg|png|pdf|docx)$')"}
{"task": "Identify requests with multiple query parameters and specific user IDs", "sql": "SELECT * FROM events WHERE regexp_like(path, '\\?user_id=\\d+&action=[a-zA-Z]+') AND user_id > 1000"}
